#include <bits/stdc++.h>
using namespace std;

bool matchesPattern(int number, const string& pattern) {
    string numStr = to_string(number);
    char previousX = '*';
    for (size_t i = 0; i < pattern.size(); ++i) {
        char ch = pattern[i];
        if (ch == '_') {
            continue;
        } else if (ch == 'X') {
            if (previousX != '*' && previousX != numStr[i]) {
                return false;
            }
            previousX = numStr[i];
        } else {
            if (numStr[i] != ch) {
                return false;
            }
        }
    }
    return true;
}

int main() {
    string input;
    getline(cin, input);
    input.erase(input.begin(), find_if(input.begin(), input.end(), [](unsigned char ch){ return !isspace(ch); }));
    input.erase(find_if(input.rbegin(), input.rend(), [](unsigned char ch){ return !isspace(ch); }).base(), input.end());
    int len = input.length();
    assert(len >= 1 && len <= 8);
    if (input[0] == '0') {
        cout << (len > 1 ? "0" : "1") << "\n";
        return 0;
    }
    int startVal = stoi("1" + string(len - 1, '0'));
    if (startVal == 1) {
        startVal = 0;
    } else if (startVal == 10) {
        startVal = 25;
    }
    int endVal = stoi(string(len, '9'));
    int totalCount = 0;
    for (int number = startVal; number <= endVal; number += 25) {
        if (matchesPattern(number, input)) {
            totalCount++;
        }
    }
    cout << totalCount << "\n";
    return 0;
}

